// Fuzz the *standalone* coupled port with valid but widely varying Thevenin
// impedances, not just those generated by the specific TrebleAttack ladder.
// These are incremental voltages; the extreme grid intentionally does not
// claim 9 V rail compliance or any physical pedal response.
#include "../src/dsp/JfetStage.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <random>

int main() {
    std::mt19937_64 gen{0x132b41c0};
    std::uniform_real_distribution<double> v(-500.0, 500.0);
    std::uniform_real_distribution<double> logR(-1.0, 14.0);
    std::uniform_real_distribution<double> logBeta(-5.0, -1.0);
    std::uniform_real_distribution<double> pinch(0.05, 3.0);
    double worstSource=0.0, worstDrain=0.0, worstPort=0.0;
    int worstIters=0;
    for (int n=0; n<100000; ++n) {
        const double fs = (n%3==0 ? 8000.0 : (n%3==1 ? 48000.0 : 384000.0));
        const double beta = std::pow(10.0, logBeta(gen));
        const double vto = -pinch(gen);
        const double input = v(gen);
        const double open = v(gen);
        const double rth = std::pow(10.0, logR(gen));

        JfetStage j;
        j.prepare(fs);
        j.setPhysicalSourceFeedbackModel(true, beta, vto);
        const double vov = j.probePhysicalOverdriveVoltage();
        const double idq = j.probePhysicalBiasCurrent();
        const double id = -j.processCoupled(input, open, rth);
        const double vs = j.probePhysicalSourceVoltage();
        const double vd = j.probeCoupledDrainVoltage();
        const double gc2 = 2.0 * fs * JfetStage::kC2;
        const double gRin = 1.0 / (JfetStage::kR4 + JfetStage::kR5);
        const double vg = gc2 * input / (gc2 + gRin) *
                          JfetStage::kR5 / (JfetStage::kR4 + JfetStage::kR5);
        const double expected = beta * std::pow(std::max(0.0, vov+vg-vs), 2) -
                                idq + (vd-vs)/JfetStage::kRo;
        const double gBase = 1.0/JfetStage::kR6 + 2.0*fs*JfetStage::kC3;
        const double sourceError = gBase*vs-id;
        const double drainError = id-expected;
        const double portError = (vd-open+rth*id) / (1.0+std::abs(vd)+std::abs(open)+std::abs(rth*id));
        if (!std::isfinite(id) || !std::isfinite(vs) || !std::isfinite(vd) ||
            !std::isfinite(sourceError) || !std::isfinite(drainError) || !std::isfinite(portError)) {
            std::fprintf(stderr, "FAIL nonfinite n%d fs%.0f beta%.4g vto%.4g x%.4g open%.4g rth%.4g\n",
                         n, fs, beta, vto, input, open, rth);
            return 1;
        }
        worstSource = std::max(worstSource, std::abs(sourceError));
        worstDrain = std::max(worstDrain, std::abs(drainError));
        worstPort = std::max(worstPort, std::abs(portError));
        worstIters = std::max(worstIters, j.probeCoupledIterations());
        if (std::abs(sourceError) > 1e-8*(1+std::abs(id)) ||
            std::abs(drainError) > 1e-8*(1+std::abs(id)) ||
            std::abs(portError) > 1e-8) {
            std::fprintf(stderr, "FAIL KCL n%d source%.17g drain%.17g port%.17g fs%.0f"
                         " beta%.4g vto%.4g x%.4g open%.4g rth%.4g iterations%d\n",
                         n, sourceError, drainError, portError, fs, beta, vto, input,
                         open, rth, j.probeCoupledIterations());
            return 1;
        }
    }
    std::printf("Coupled random Thevenin oracle: 100k one-shot KCL PASS; worst"
                " |source| %.3g A, |drain| %.3g A, relative port %.3g, iterations %d\n",
                worstSource, worstDrain, worstPort, worstIters);
}
